```
if (chooseX) {
  ball.vx = push === -1 ? -Math.abs(ball.vx) : Math.abs(ball.vx);
  ball.x = push === -1 ? hitBrick.x - ball.r : hitBrick.x + hitBrick.w + ball.r;
} else {
