import {
  collides,
  step,
  makeBricks,
  createState,
  resolveBrickCollision,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
} from './neon.js';

// --- Brick bounce (#1) ------------------------------------------------------

function brickAt(x, y) {
  return { x, y, w: 40, h: 20, alive: true };
}

function ballAt(x, y, vx, vy) {
  return { x, y, r: 8, vx, vy };
}

test('resolve: head-on top hit flips vy (up becomes down), keeps vx, pushes out', () => {
  const ball = ballAt(100, 50, 40, -200); // traveling UP into the brick below
  const brick = brickAt(90, 60);
  const hit = resolveBrickCollision(ball, [brick], ball.x, ball.y - 5);
  assert.equal(hit, brick);
  assert.ok(ball.vy > 0, 'vy should flip downward');
  assert.ok(ball.vx > 0, 'vx is untouched and keeps heading right');
  assert.ok(ball.y + ball.r < brick.y, 'ball pushed out above the brick');
});

test('resolve: side hit flips vx, keeps vy, pushes out horizontally', () => {
  const ball = ballAt(60, 70, -200, 40); // traveling LEFT into the brick's right face
  const brick = brickAt(90, 60);
  const hit = resolveBrickCollision(ball, [brick], ball.x + 5, ball.y);
  assert.equal(hit, brick);
  assert.ok(ball.vx > 0, 'vx should flip back rightward');
  assert.ok(ball.vy > 0, 'vy is untouched and keeps heading down');
  assert.ok(ball.x + ball.r < brick.x, 'ball pushed out left of the brick');
});

test('resolve: corner hit flips BOTH components', () => {
  const ball = ballAt(80, 70, -200, -200); // diagonal into top-left corner
  const brick = brickAt(90, 60);
  const hit = resolveBrickCollision(ball, [brick], ball.x + 6, ball.y + 6);
  assert.equal(hit, brick);
  assert.ok(ball.vx > 0, 'vx flipped to the right');
  assert.ok(ball.vy > 0, 'vy flipped downward');
});

test('resolve: tunnelling ball is caught by the sweep', () => {
  // Ball starts below the brick and vaults PAST it in one step (no overlap at
  // either endpoint), exactly the frame-skip bug the sweep fixes.
  const brick = brickAt(90, 60);
  const ball = ballAt(105, 120, 0, -300);
  // Previous frame position is far below the brick; current sits far above it.
  const hit = resolveBrickCollision(ball, [brick], ball.x, ball.y + 40);
  assert.equal(hit, brick);
  assert.ok(ball.vy > 0, 'bounce happened, so the ball is heading back down');
});

test('resolve: no overlap => no hit, velocity untouched', () => {
  const brick = brickAt(90, 60);
  const ball = ballAt(10, 10, 50, 50);
  const hit = resolveBrickCollision(ball, [brick], ball.x, ball.y);
  assert.equal(hit, null);
  assert.equal(ball.vx, 50);
  assert.equal(ball.vy, 50);
});

