// Main render loop. For each live brick we test collision AND draw in the same
// pass: this is where logic and rendering are entangled.
export function frame(ctx, state) {
  // Background
  ctx.fillStyle = palette.background;
  ctx.fillRect(0, 0, WIDTH, HEIGHT);

  // Bricks: bounce the ball against them (once), then draw the survivors.
  // Collision resolution is delegated to the pure `resolveBrickCollision`
  // (#1): it bounces the ball and tells us which brick to break. Drawn dead
  // bricks are skipped, so the hit brick disappears.
  const hit = resolveBrickCollision(state.ball, state.bricks, state.ball.px, state.ball.py);
  if (hit) {
    hit.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(hit, state.combo);
  }

  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    ctx.fillStyle = brickColor(brick.row);
    ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
